wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1303613000920349640)
,p_plug_name=>'Store Overview'
,p_title=>'Store Overview'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_plug_grid_column_span=>12
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT 1 AS display_order,',
'       ''Completed Sales'' AS card_title,',
'       TO_CHAR(',
'           NVL(SUM(total_amount), 0),',
'           ''FM999,999,999,990.00''',
'       ) AS card_value,',
'       ''Total value of completed orders'' AS card_description',
'FROM orders',
'WHERE status = ''Completed''',
'',
'UNION ALL',
'',
'SELECT 2,',
'       ''Total Orders'',',
'       TO_CHAR(COUNT(*)),',
'       ''All orders, including pending and cancelled''',
'FROM orders',
'',
'UNION ALL',
'',
'SELECT 3,',
'       ''Customers'',',
'       TO_CHAR(COUNT(*)),',
'       ''Customers registered in your store''',
'FROM customers',
'',
'UNION ALL',
'',
'SELECT 4,',
'       ''Low Stock'',',
'       TO_CHAR(COUNT(*)),',
'       ''Products with fewer than 20 units''',
'FROM products',
'WHERE stock_quantity < 20',
'',
'ORDER BY display_order'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
