,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div style="',
'  display: grid;',
'  grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr));',
'  align-items: center;',
'  gap: 32px;',
'  background: linear-gradient(135deg, #FAF7F5, #F5E2E8);',
'  border-radius: 24px;',
'  padding: clamp(24px, 4vw, 48px);',
'  color: #302630;',
'">',
'',
'  <div>',
'    <p style="',
'      color: #9D3D60;',
'      font-size: 13px;',
'      font-weight: 700;',
'      letter-spacing: 3px;',
'      margin: 0 0 16px;',
'    ">',
unistr('      BEAUTY \00B7 CARE \00B7 CONFIDENCE'),
'    </p>',
'',
'    <h1 style="',
'      font-size: clamp(32px, 4vw, 48px);',
'      line-height: 1.15;',
'      margin: 0 0 20px;',
'      color: #302630;',
'    ">',
unistr('      Welcome to Glamor\00E9'),
'    </h1>',
'',
'    <p style="',
'      font-size: 17px;',
'      line-height: 1.7;',
'      margin: 0 0 28px;',
